B.bxi=s(["\u0443-\u0442\u043a\u0430","\u043b\u0438-\u0441\u0430","\u043c\u043e-\u0441\u0442","\u043a\u0430-\u0440\u0430\u043d-\u0434\u0430\u0448"],t.s)
B.bPL=new A.dp("\u0421\u043b\u043e\u0433 \u2014 \u044d\u0442\u043e \u043d\u0430\u0438\u043c\u0435\u043d\u044c\u0448\u0430\u044f \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0435\u0434\u0438\u043d\u0438\u0446\u0430 \u0440\u0435\u0447\u0438, \u043f\u043e\u0440\u0446\u0438\u044f \u0432\u043e\u0437\u0434\u0443\u0445\u0430, \u0432\u044b\u0442\u0430\u043b\u043a\u0438\u0432\u0430\u0435\u043c\u0430\u044f \u0437\u0430 \u043e\u0434\u0438\u043d \u0442\u043e\u043b\u0447\u043e\u043a \u043b\u0435\u0433\u043a\u0438\u0445. \u0412 \u0440\u0443\u0441\u0441\u043a\u043e\u043c \u044f\u0437\u044b\u043a\u0435 \u0441\u043b\u043e\u0433\u043e\u043e\u0431\u0440\u0430\u0437\u0443\u044e\u0449\u0438\u043c\u0438 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0437\u0432\u0443\u043a\u0438. \u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0432 \u0441\u043b\u043e\u0432\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u2014 \u0440\u043e\u0432\u043d\u043e \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0438 \u0441\u043b\u043e\u0433\u043e\u0432! \u0423\u0434\u0430\u0440\u0435\u043d\u0438\u0435 \u2014 \u044d\u0442\u043e \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u0441\u043b\u043e\u0433\u043e\u0432 \u0441\u0438\u043b\u043e\u0439 \u0432\u044b\u0434\u043e\u0445\u0430, \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u044e \u0437\u0432\u0443\u0447\u0430\u043d\u0438\u044f \u0438 \u0432\u044b\u0441\u043e\u0442\u043e\u0439 \u0433\u043e\u043b\u043e\u0441\u0430. \u0423\u0434\u0430\u0440\u0435\u043d\u0438\u0435 \u0432 \u0440\u0443\u0441\u0441\u043a\u043e\u043c \u044f\u0437\u044b\u043a\u0435 \u043f\u043e\u0434\u0432\u0438\u0436\u043d\u043e\u0435 \u0438 \u0440\u0430\u0437\u043d\u043e\u043c\u0435\u0441\u0442\u043d\u043e\u0435, \u043e\u043d\u043e \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e \u043c\u0435\u043d\u044f\u0442\u044c \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0441\u043b\u043e\u0432\u0430 (\u0437\u0430\u0301\u043c\u043e\u043a \u2014 \u0437\u0430\u043c\u043e\u0301\u043a, \u043a\u0440\u0443\u0301\u0436\u043a\u0438 \u2014 \u043a\u0440\u0443\u0436\u043a\u0438\u0301). \u041f\u0440\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435 \u0441\u043b\u043e\u0432 \u043d\u0435\u043b\u044c\u0437\u044f \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u0442\u044c \u0441\u043b\u043e\u0433\u0438 \u0438 \u043d\u0435\u043b\u044c\u0437\u044f \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u043e\u0434\u043d\u0443 \u0431\u0443\u043a\u0432\u0443 \u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0435.",B.blr,"\u0414\u0435\u0442\u0438 \u0447\u0430\u0441\u0442\u043e \u0434\u0435\u043b\u044f\u0442 \u0441\u043b\u043e\u0432\u0430 \u043d\u0430 \u0441\u043b\u043e\u0433\u0438 \u043f\u043e \u0441\u043c\u044b\u0441\u043b\u0443 \u0438\u043b\u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u0443 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u0430 (\u0434\u0443\u043c\u0430\u044f, \u0447\u0442\u043e \u0432 \u0441\u043b\u043e\u0432\u0435 \u0421\u041b\u041e\u041d \u043c\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u0433\u043e\u0432, \u0432\u0435\u0434\u044c \u0441\u043b\u043e\u043d \u043e\u0433\u0440\u043e\u043c\u043d\u044b\u0439, \u0430 \u0432 \u0441\u043b\u043e\u0432\u0435 \u0411\u0423\u041a\u0410\u0428\u0415\u0427\u041a\u0410 \u2014 \u043c\u0430\u043b\u043e). \u0412\u0442\u043e\u0440\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430: \u043f\u043e\u043f\u044b\u0442\u043a\u0430 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043e\u0434\u043d\u0443 \u0433\u043b\u0430\u0441\u043d\u0443\u044e \u0431\u0443\u043a\u0432\u0443 \u043d\u0430 \u043d\u043e\u0432\u0443\u044e \u0441\u0442\u0440\u043e\u043a\u0443 (*\u043e-\u0441\u0438\u043d\u0430*).","\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0432 \u0441\u043b\u043e\u0432\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u2014 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0438 \u0441\u043b\u043e\u0433\u043e\u0432, \u044d\u0442\u043e \u0437\u043d\u0430\u0435\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u0438\u0437 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432! \u041e\u0434\u043d\u0443 \u0431\u0443\u043a\u0432\u0443 \u043d\u0435 \u0431\u0440\u043e\u0441\u0430\u0439, \u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0435 \u043d\u0435 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0439!",'\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0420\u0435\u0431\u044f\u0442\u0430, \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435 \u043b\u0430\u0434\u043e\u0448\u043a\u0443 \u0442\u044b\u043b\u044c\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u043e\u0439 \u043f\u043e\u0434 \u043f\u043e\u0434\u0431\u043e\u0440\u043e\u0434\u043e\u043a \u0438 \u0447\u0435\u0442\u043a\u043e \u043f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u0438\u0442\u0435 \u0441\u043b\u043e\u0432\u043e: \u041c\u0410-\u0428\u0418-\u041d\u0410. \u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u043f\u043e\u0434\u0431\u043e\u0440\u043e\u0434\u043e\u043a \u043a\u043e\u0441\u043d\u0443\u043b\u0441\u044f \u043b\u0430\u0434\u043e\u043d\u0438?"\n\u0414\u0435\u0442\u0438: "\u0422\u0440\u0438 \u0440\u0430\u0437\u0430!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0410 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u0437\u0432\u0443\u043a\u043e\u0432 \u0432 \u044d\u0442\u043e\u043c \u0441\u043b\u043e\u0432\u0435?"\n\u041c\u0438\u0448\u0430: "\u0410, \u0418, \u0410 \u2014 \u0440\u043e\u0432\u043d\u043e \u0442\u0440\u0438!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0412\u0435\u0440\u043d\u043e! \u041a\u0430\u0436\u0434\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0432\u0443\u043a \u0440\u0430\u0441\u043f\u0430\u0445\u0438\u0432\u0430\u0435\u0442 \u0440\u043e\u0442 \u0438 \u043e\u0431\u0440\u0430\u0437\u0443\u0435\u0442 \u0441\u0432\u043e\u0439 \u0441\u043b\u043e\u0433. \u0410 \u0442\u0435\u043f\u0435\u0440\u044c \u043f\u043e\u0437\u043e\u0432\u0435\u043c \u0441\u043b\u043e\u0432\u043e: \u041c\u0430\u0448\u0438-\u0438-\u0438\u043d\u0430! \u041d\u0430 \u043a\u0430\u043a\u043e\u0439 \u0441\u043b\u043e\u0433 \u0443\u043f\u0430\u043b\u0430 \u043a\u043e\u0440\u043e\u043d\u0430 \u0443\u0434\u0430\u0440\u0435\u043d\u0438\u044f?"\n\u0414\u0435\u0442\u0438: "\u041d\u0430 \u0432\u0442\u043e\u0440\u043e\u0439 \u0441\u043b\u043e\u0433, \u043d\u0430 \u0437\u0432\u0443\u043a \u0418!"',B.aXl,B.bfA,'\u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0430 \u0433\u043e\u0432\u043e\u0440\u0438\u0442: "\u0412 \u0441\u043b\u043e\u0432\u0435 \u0421\u0422\u041e\u041b \u0434\u0432\u0430 \u0441\u043b\u043e\u0433\u0430, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0437\u0430 \u0441\u0442\u043e\u043b\u043e\u043c \u043f\u043e\u043c\u0435\u0449\u0430\u044e\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443 \u0434\u0432\u0430 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430, \u0430 \u0441\u0430\u043c \u0441\u0442\u043e\u043b \u043e\u0447\u0435\u043d\u044c \u0434\u043b\u0438\u043d\u043d\u044b\u0439!"',B.bL3,"1 - 2 - 3 - 4 - 5","\u041a\u041d\u0418\u0413\u0410","\u041d\u0430\u0439\u0434\u0438 \u0434\u0432\u0443\u0445\u0441\u043b\u043e\u0436\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u043f\u0435\u0440\u0432\u044b\u0439 \u0441\u043b\u043e\u0433 \u0441\u043e\u0441\u0442\u043e\u0438\u0442 \u0432\u0441\u0435\u0433\u043e \u0438\u0437 \u043e\u0434\u043d\u043e\u0439 \u0431\u0443\u043a\u0432\u044b, \u0430 \u0432\u0442\u043e\u0440\u043e\u0439 \u2014 \u0438\u0437 \u0442\u0440\u0451\u0445 \u0431\u0443\u043a\u0432.",B.bxi,'\u0443\u0442\u043a\u0430 (1-\u0439 \u0441\u043b\u043e\u0433 "\u0443" \u2014 1 \u0431\u0443\u043a\u0432\u0430, 2-\u0439 \u0441\u043b\u043e\u0433 "\u0442\u043a\u0430" \u2014 3 \u0431\u0443\u043a\u0432\u044b)',"\u0421\u043b\u043e\u0433\u0438 \u0434\u043b\u044f \u043f\u0440\u043e\u043f\u0438\u0441\u044b\u0432\u0430\u043d\u0438\u044f \u0432 \u043a\u043e\u0441\u043e\u0439 \u043b\u0438\u043d\u0435\u0439\u043a\u0435: \u043c\u0430, \u0448\u0438, \u043d\u0430, \u0432\u043e, \u0434\u0430, \u043b\u0438, \u0441\u0430 \u0441 \u0432\u0435\u0440\u0445\u043d\u0438\u043c \u0438 \u0441\u0440\u0435\u0434\u043d\u0438\u043c \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435\u043c.","1. \u041e\u0431\u0440\u0430\u0437\u0435\u0446: \u0434\u043e\u043c \u2014 1 \u0441\u043b\u043e\u0433, \u043b\u0438-\u0441\u0430 \u2014 2 \u0441\u043b\u043e\u0433\u0430. 2. \u0421\u0442\u0440\u0435\u043b\u043a\u0438: \u0448\u0430\u0440 -> 1 \u0441\u043b\u043e\u0433, \u0432\u043e-\u0434\u0430 -> 2 \u0441\u043b\u043e\u0433\u0430, \u043a\u0430-\u0440\u0430\u043d-\u0434\u0430\u0448 -> 3 \u0441\u043b\u043e\u0433\u0430. 3. \u0422\u0430\u0431\u043b\u0438\u0446\u0430: 1 \u0441\u043b\u043e\u0433: \u0434\u043e\u043c, \u043a\u043e\u0442, \u0448\u0430\u0440; 2 \u0441\u043b\u043e\u0433\u0430: \u0432\u043e-\u0434\u0430, \u043a\u043d\u0438-\u0433\u0430, \u043b\u0438-\u0441\u0430; 3 \u0441\u043b\u043e\u0433\u0430: \u043c\u0430-\u0448\u0438-\u043d\u0430, \u043a\u0430-\u0440\u0430\u043d-\u0434\u0430\u0448. 4. \u041e\u0448\u0438\u0431\u043a\u0430 \u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0438: \u0441\u043b\u043e\u0433 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u043e \u0433\u043b\u0430\u0441\u043d\u044b\u043c, \u0432 \u0441\u043b\u043e\u0432\u0435 \u0421\u0422\u041e\u041b \u043e\u0434\u043d\u0430 \u0433\u043b\u0430\u0441\u043d\u0430\u044f \u041e. 7. \u0428\u0438\u0444\u0440: \u041a\u041d\u0418\u0413\u0410. 8. \u0422\u0420\u0418\u0417: \u0443\u0442\u043a\u0430.")
B.btd=s(["\u0427\u0438\u0441\u043b\u043e\u0432\u043e\u0439 \u0434\u043e\u043c\u0438\u043a: \u043d\u0430 \u043a\u0440\u044b\u0448\u0435 \u0436\u0438\u0432\u0435\u0442 \u0447\u0438\u0441\u043b\u043e (\u0445\u043e\u0437\u044f\u0438\u043d), \u0430 \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u044d\u0442\u0430\u0436\u0435 \u0432 \u0434\u0432\u0443\u0445 \u043a\u043e\u043c\u043d\u0430\u0442\u043a\u0430\u0445 \u0436\u0438\u0432\u0443\u0442 \u043f\u0430\u0440\u044b \u0447\u0438\u0441\u0435\u043b-\u0441\u043e\u0441\u0435\u0434\u0435\u0439.","\u0414\u0432\u0435 \u043b\u0430\u0434\u043e\u0448\u043a\u0438: \u0447\u0438\u0441\u043b\u043e 5 \u2014 \u044d\u0442\u043e 4 \u043f\u0430\u043b\u044c\u0447\u0438\u043a\u0430 \u043d\u0430 \u043e\u0434\u043d\u043e\u0439 \u0440\u0443\u043a\u0435 \u0438 1 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0439, \u0438\u043b\u0438 3 \u0438 2."],t.s)
B.bv8=s(["\u0421\u043e\u0441\u0442\u0430\u0432 \u0447\u0438\u0441\u043b\u0430 5","\u0421\u043e\u0441\u0442\u0430\u0432 \u0447\u0438\u0441\u043b\u0430 6","\u0421\u043e\u0441\u0442\u0430\u0432 \u0447\u0438\u0441\u043b\u0430 7"],t.s)
B.bgM=s(["4 + 1","3 + 2","5 + 1","4 + 2","3 + 3","6 + 1","5 + 2","4 + 3"],t.s)
